Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -109,8 +109,9 @@
  // layered rolling hills
  for(let layer=0;layer<2;layer++){let par=layer?.28:.12;ctx.fillStyle=layer?theme.hill:theme.far;ctx.beginPath();ctx.moveTo(0,H);for(let x=-100;x<vw+150;x+=18){let worldx=x+cam*par;let y=layer?365+Math.sin(worldx*.006)*29+Math.sin(worldx*.013)*15:315+Math.sin(worldx*.004)*36+Math.sin(worldx*.01)*18;ctx.lineTo(x,y)}ctx.lineTo(vw,H);ctx.closePath();ctx.fill();}
  // decorative trees / mushrooms
  for(let i=0;i<Math.ceil(vw/110)+3;i++){let x=((i*151-cam*.45)%(vw+180)+vw+180)%(vw+180)-70;let y=385+(i%3)*13;drawTree(x,y,theme,i)}
+ if(!levelData){ctx.fillStyle='#fff';ctx.fillRect(0,FLOOR,vw,H-FLOOR);ctx.fillStyle='#62cb76';ctx.fillRect(0,FLOOR,vw,10);return;}
  ctx.save();let shakeX=shake?Math.sin(performance.now()*.08)*shake:0;ctx.translate(-cam+shakeX,0);
  for(const plat of levelData?.platforms||[]){drawPlatform(plat,theme)}
  // collectible trails
  for(const c of levelData?.coins||[]){if(!c.taken)drawCoin(c.x,c.y,performance.now()/300)}

